//! Golden test: tool-argument validation matches pi-ai `validateToolArguments`
//! (fixture generated by `scripts/pi-oracle/core-runtime/agent/validation.mjs`).

#![allow(
    clippy::unwrap_used,
    clippy::expect_used,
    clippy::panic,
    reason = "tests assert by unwrapping"
)]

use oino_agent::validate_tool_arguments;
use oino_ai::json::json_semantic_eq;
use oino_ai::{JsonValue, ToolCall};

#[test]
fn validation_matches_pi() {
    let path = format!(
        "{}/tests/fixtures/validation.json",
        env!("CARGO_MANIFEST_DIR")
    );
    let fixture: JsonValue = serde_json::from_str(&std::fs::read_to_string(path).unwrap()).unwrap();
    let mut failures = Vec::new();
    for case in fixture["cases"].as_array().unwrap() {
        let schema = &fixture["schemas"][case["schema"].as_str().unwrap()];
        let call = ToolCall {
            id: "id".into(),
            name: "t".into(),
            arguments: case["args"].as_object().cloned().unwrap_or_default(),
            arguments_error: case["argumentsError"].as_str().map(str::to_owned),
            ..ToolCall::default()
        };
        let actual = validate_tool_arguments(schema, &call);
        let ok = match (&actual, case.get("ok"), case.get("error")) {
            (Ok(args), Some(expected), _) => {
                json_semantic_eq(&JsonValue::Object(args.clone()), expected)
            }
            (Err(message), _, Some(expected)) => Some(message.as_str()) == expected.as_str(),
            _ => false,
        };
        if !ok {
            failures.push(format!(
                "{}: {:?}\n  expected {}",
                case["args"], actual, case
            ));
        }
    }
    assert!(failures.is_empty(), "{}", failures.join("\n"));
}
